(()=>{
 const sources={desktop:'data:image/webp;base64,',mobile:'data:image/webp;base64,'};
 let dispose=()=>{};
 window.setupHeroLines=()=>{
  dispose();
  const scene=document.querySelector('.hero-scene'),photo=scene?.querySelector('.hero-image');
  if(!photo)return;
  const lines=document.createElement('div');lines.className='hero-light-lines';lines.setAttribute('aria-hidden','true');
  lines.innerHTML='<svg viewBox="0 0 1440 700" preserveAspectRatio="none"><defs><linearGradient id="pc-line-spectrum" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#8e69ef"/><stop offset=".28" stop-color="#8cb5ff"/><stop offset=".53" stop-color="#65c9d7"/><stop offset=".76" stop-color="#e4a3b9"/><stop offset="1" stop-color="#edb985"/></linearGradient></defs><g fill="none" stroke="url(#pc-line-spectrum)" stroke-linecap="round"><path class="line-halo" d="M-100 540 C80 425 160 165 410 130 S1050 -20 1540 480"/><path class="line-core" d="M-100 540 C80 425 160 165 410 130 S1050 -20 1540 480"/><path class="line-secondary" d="M-100 567 C90 442 175 184 420 150 S1060 5 1540 505"/></g></svg>';
  scene.prepend(lines);
  const canvas=document.createElement('canvas');canvas.className='hero-product-cutout';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',photo.alt);scene.append(canvas);
  const context=canvas.getContext('2d'),mobile=matchMedia('(max-width:650px)');let dead=false,key='',revision=0;
  function place(){if(dead)return;const a=photo.getBoundingClientRect(),b=scene.getBoundingClientRect();Object.assign(canvas.style,{left:a.left-b.left+'px',top:a.top-b.top+'px',width:a.width+'px',height:a.height+'px'});}
  function render(){
   if(dead)return;place();const selected=mobile.matches?'mobile':'desktop';if(key===selected)return;key=selected;const token=++revision;
   const input=new Image();input.onload=()=>{if(dead||token!==revision)return;canvas.width=input.naturalWidth;canvas.height=input.naturalHeight;context.drawImage(input,0,0);const data=context.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<data.data.length;i+=4){const v=Math.max(data.data[i],data.data[i+1],data.data[i+2]);data.data[i+3]=v<=8?0:v>=20?255:Math.round((v-8)/12*255);}context.putImageData(data,0,0);scene.classList.add('hero-lines-ready');place();};input.src=sources[selected];
  }
  const observer=new ResizeObserver(render);observer.observe(scene);observer.observe(photo);photo.addEventListener('load',render);mobile.addEventListener('change',render);render();
  dispose=()=>{dead=true;observer.disconnect();photo.removeEventListener('load',render);mobile.removeEventListener('change',render);lines.remove();canvas.remove();scene.classList.remove('hero-lines-ready');};
 };
})();
